CREATE SCHEMA IF NOT EXISTS drakkar;

CREATE TABLE IF NOT EXISTS drakkar.fleet_workers (
    worker        text        PRIMARY KEY,
    instance      text        NOT NULL,
    cluster       text        NOT NULL,
    card          text        NOT NULL,
    heartbeat_at  timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS fleet_workers_cluster_idx ON drakkar.fleet_workers (cluster);

CREATE INDEX IF NOT EXISTS fleet_workers_heartbeat_idx ON drakkar.fleet_workers (heartbeat_at);

CREATE TABLE IF NOT EXISTS drakkar.task_locks (
    scope         text        PRIMARY KEY,
    token         text        NOT NULL,
    worker        text        NOT NULL,
    instance      text        NOT NULL,
    acquired_at   timestamptz NOT NULL DEFAULT now(),
    refreshed_at  timestamptz NOT NULL DEFAULT now()
);

